文本提交 实现 TextCommitSink::commit(std::string_view)，在回调返回前接收完整的 UTF-8 文本。以下内存接收器使用固定容量： #include <hanime/core.hpp>
#include <array>
#include <cstring>

class TextBuffer final : public hanime::TextCommitSink {
 public:
  std::array<char, 1024> bytes{};
  std::size_t used = 0;

  bool commit(std::string_view text) override {
    if (text.size() > bytes.size() - used) return false;
    if (!text.empty()) std::memcpy(bytes.data() + used, text.data(), text.size());
    used += text.size();
    return true;
  }
};
 它不追加字符串终止符，读取时用 used 确定字节长度。编辑器接收器必须保证一次提交完整接收或完全不改变文档：true 表示已接收；false 必须表示没有产生任何效果。不要写入半段后返回 false。 Core 的 confirm() 开始一次候选提交，随后 tick() 推进到终态。Extension 则在所有编码都已选择后执行 Submission::prepare() → advance() → confirm()，一次提交整个组合的 UTF-8 文本。Accepted 表示应用接收成功，不表示文稿已写入磁盘，也不表示个人学习已保存。 收到 RetryableNoEffect 时，只能使用接口提供的重试许可或当次事务重试。收到 UnknownOutcome 时不要重新插入文字：应用可能已经改动，需要先核对接收端状态。成功后的学习错误也不能通过再次提交正文来恢复。

候选查询与提交示例 以下示例提取自 host_minimal，处理第一页候选。先用该示例的 Resources 打开并校验文件，再创建 NoLearning、DemoDocument 和 CandidateSession，完成文字准入。会话配置至少允许一个候选，编码和文字容量需容纳资源中的数据；示例采用 SessionConfig{4, 1, 1, 64, 64, 32}。这些所有者必须晚于会话销毁，下面的控制对象又必须先于会话销毁。 #include <hanime/candidate_session.hpp>
#include <string>

namespace docs_core {
using namespace hanime;
struct Frame { std::string text; SelectionHandle choice; OutputStatus output{OutputStatus::Pending}; };

// session 已完成资源校验和文字准入，且比这个控制对象活得更久。
class FirstCandidate {
 public:
  explicit FirstCandidate(CandidateSession& session) : session_(session) {}
  Frame frame;

  // 完整编码输入事件：先查身份，再按需取字。这里明确禁用个人排序。
  SessionStatus start(std::string_view code, MountEpoch epoch) {
    if (phase_ != Phase::Idle) return SessionStatus::Busy;
    frame = {};
    status_ = session_.begin_input(code, epoch, 1, 0, ScoringMode::BaseOnly);
    if (status_ == SessionStatus::Pending) phase_ = Phase::Rank;
    return status_;
  }

  // 调度循环：每次只推进一步；返回 Ready 后才能显示 frame。
  SessionStatus advance(const WorkBudget& budget) {
    if (phase_ == Phase::Idle) return status_;
    status_ = session_.tick(budget).status;
    if (status_ == SessionStatus::Pending || status_ == SessionStatus::WaitingState)
      return status_;
    if (status_ != SessionStatus::StagingReady) return stop(status_);
    if (phase_ == Phase::Rank) {
      status_ = session_.publish(session_.staging());
      if (status_ != SessionStatus::Ready) return stop(status_);
      status_ = session_.request_text(session_.published(), 0, 1);
      if (status_ != SessionStatus::Pending) return stop(status_);
      phase_ = Phase::Text;
      return status_;
    }
    // 取字完成更新的是已发布页，不需要再次 publish。
    Frame next;
    bool order_stale = false;
    status_ = session_.present([&](const CandidateViewPage& page) {
      order_stale = page.order_stale;
      if (page.size) {
        next.output = page.items[0].output;
        if (!order_stale && output_has_text(next.output)) {
          next.text = page.text(0);
          next.choice = session_.selection(0);
        }
      }
    });
    if (status_ == SessionStatus::Ready && order_stale)
      return stop(SessionStatus::NeedsRankRestart);
    if (status_ == SessionStatus::Ready) frame = next;
    return stop(status_);
  }

  // 选择事件：传入用户实际看到的那一帧，不能临时换成新页的同一位置。
  CommitResult choose(const Frame& shown) { return session_.confirm(shown.choice); }
  // 调度循环：Preparing 之后持续推进，Accepted 才表示接收成功。
  CommitResult advance_commit(const WorkBudget& budget) {
    auto result = session_.commit_result();
    if (result.status == CommitStatus::Preparing || result.status == CommitStatus::CallingSink)
      session_.tick(budget);
    return session_.commit_result();
  }
 private:
  enum class Phase { Idle, Rank, Text };
  CandidateSession& session_;
  Phase phase_{Phase::Idle};
  SessionStatus status_{SessionStatus::Idle};
  SessionStatus stop(SessionStatus status) { phase_ = Phase::Idle; return status_ = status; }
};
} // namespace docs_core
 输入事件调用 start("yuanxingji", 1)；这里的 1 必须就是资源的挂载代次。调度器以 WorkBudget{1, 17, 3} 调用 advance()，仅在 Pending 或 WaitingState 时继续，Ready 后复制 frame 供渲染层读取。没有可输出文字时，帧中没有可确认的选择，应显示相应输出状态。 选择事件向 choose() 传入对应的显示帧。返回 Preparing 后调度 advance_commit()，直到 Accepted 或其他终态。若中途开始了新输入，再确认旧帧会得到 Stale：丢弃旧帧并刷新候选，不能自动确认新页。查询返回 ReadError 等错误时停止推进并处理资源问题；提交返回 RetryableNoEffect 或 UnknownOutcome 时按后面的规则处理，不自动重放。这个精简控制对象不处理翻页、输入取消或重试，完整实现见 host_minimal 的 query()、display()、submit()。

组合输入与提交示例 以下示例采用 host_composition 的命令行调度方式。先按示例创建并校验 Resources，创建 DemoDocument，再构造 Composition 和 Submission，分别检查 valid()。全拼使用 resources.full 与 FullPinyin，小鹤使用 resources.xiaohe 与 R1Xiaohe；两个对象使用默认容量、关闭学习。下面的函数借用这些对象，不延长其生命期。 #include <hanime_extension/submission.hpp>
#include <stdexcept>
#include <string>

namespace docs_composition {
namespace ex = hanime_extension;
constexpr hanime::WorkBudget budget{1, 17, 3};
constexpr std::size_t limit = 100000;

// 命令行示例的调度循环。GUI 应保存 operation，每次调度只调用一次 tick。
ex::Status finish(ex::Composition& input, ex::Status status) {
  const auto operation = input.operation();
  for (std::size_t n = 0; status == ex::Status::Working; ++n) {
    if (n == limit) throw std::runtime_error("input operation did not finish");
    status = input.tick(operation, budget).status;
  }
  return status; // 原样保留 Stale、Busy、资源错误等结果。
}

// 字符事件；这里只示范尾部追加，删除改用相应的 edit_raw 字节区间。
ex::Status append_key(ex::Composition& input, char key) {
  const auto end = input.raw_input().raw.size();
  const auto edited = input.edit_raw(end, end, std::string_view(&key, 1));
  return edited == ex::Status::Ready ? finish(input, input.query_next()) : edited;
}
struct Frame { ex::Selection choice; std::string text; };
ex::Status read_first(ex::Composition& input, Frame& frame) {
  frame = {};
  if (input.status() != ex::Status::PageReady || input.page().size == 0)
    return ex::Status::InvalidRequest;
  const auto choice = input.selection(0);
  const auto status = finish(input, input.read_text(choice));
  if (status == ex::Status::Ready) frame = {choice, std::string(input.last_text())};
  return status;
}
// 用户选择事件；传入显示时保存的选择，不能重新按页内序号取候选。
ex::Status choose(ex::Composition& input, const Frame& shown) {
  return finish(input, input.select(shown.choice));
}

struct Prepared { ex::SubmissionResult result; std::string text; };
Prepared prepare(ex::Submission& submission) {
  Prepared prepared{submission.prepare(ex::InputTarget::Body), {}};
  for (std::size_t n = 0;
       prepared.result.core.status == hanime::CompositionStatus::Preparing; ++n) {
    if (n == limit) throw std::runtime_error("submission did not finish");
    // 调度循环；每一步使用同一次尝试的句柄。
    prepared.result = submission.advance(prepared.result.transaction, budget).result;
  }
  if (prepared.result.core.status == hanime::CompositionStatus::Ready) {
    const auto status = submission.prepared(prepared.result.transaction,
        [&](const hanime::PreparedCompositionView& view) { prepared.text = view.text; });
    if (status != hanime::CompositionStatus::Ready) prepared.result.core.status = status;
  }
  return prepared; // 此时只是准备好文字，尚未调用接收器。
}
// 确认提交事件；调用者必须先检查 prepare 的结果为 Ready。
ex::SubmissionResult confirm(ex::Submission& submission, const Prepared& prepared) {
  return submission.confirm(prepared.result.transaction);
}
} // namespace docs_composition
 全拼输入逐字符调用 append_key() 追加 yuanxingji。前缀可能返回 NoPrefixMatch、NoMappingForPrefix 或 Unresolved，继续接收编码；完整词到 PageReady 后调用 read_first()，得到「原型机」和对应选择。若查询被取消或资源失效，保留实际错误并停止使用该次候选。 显示后，由选词事件调用 choose()。返回 Stale 时丢弃那份帧并重新查询，返回 Ready 后检查 snapshot().state：PartialSelected 需要继续查询和选词，AllSelected 才进入 prepare()。检查返回的 result.core.status == Ready，再向 confirm() 传入同一份 Prepared；Accepted 表示接收器已接受一次完整文本。输出预览已经复制，不能用它自行插入文字来代替确认事务。 两个循环仅适合命令行示例；接入界面时，将 tick()、advance() 的单步调用放入调度器，保存操作或提交句柄，并在下一轮处理返回状态。达到示例的步数上限只表示宿主停止等待，不代表引擎自动取消：继续编辑前应显式取消当前操作或提交尝试。正常流程、重复确认与过期选择可对照 host_composition；RetryableNoEffect 和 UnknownOutcome 仍需按下表实现宿主恢复操作。

直接查询与提交示例 沿用 host_wubi86 的 Resources、NoLearning 和 DemoDocument：资源已经完整校验，NoLearning 提供固定计数所有者与命名空间，但不读取或记录个人次数。按顺序创建 Wubi86Decoder、CandidateSession(index, shared, counts, sink, {4, 2, 1, 64, 64, 4}) 和 DirectQueryBinding(decoder, session, index, shared, 1)。完成会话文字准入、设置输出后，检查 binding.activate() == SessionStatus::Ready。绑定先销毁，随后才是会话、解码器及其他所有者。 #include <hanime_wubi/wubi.hpp>
#include <stdexcept>
#include <string>

namespace docs_wubi {
using namespace hanime;
namespace wb = hanime::wubi;
constexpr WorkBudget budget{1, 17, 3};
constexpr std::size_t limit = 100000;
struct Query { wb::EditStatus edit; wb::Step step; };

// 字符事件 + 命令行调度；page_size 要与构造绑定时相同。
Query key(wb::DirectQueryBinding& binding, CandidateSession& session,
          std::size_t page_size, char character) {
  Query result{binding.append(character), {}};
  if (result.edit != wb::EditStatus::Changed) return result;
  // 与 host_wubi86 一致：第一次 tick 只建立逻辑输入。
  result.step = binding.tick(budget);
  if (result.step.shared.status != SessionStatus::Pending) return result;
  // 本示例无个人状态，在任何计数读取前明确改用基础排序。
  result.step.shared.status = session.restart_first(page_size, page_size, ScoringMode::BaseOnly);
  for (std::size_t n = 0; result.step.shared.status == SessionStatus::Pending; ++n) {
    if (n == limit) throw std::runtime_error("Wubi query did not finish");
    result.step = binding.tick(budget); // GUI 每次调度只做一步。
  }
  return result; // Ready、NoMatches 或实际错误；这里从未调用 confirm。
}
struct Frame { std::string text; SelectionHandle choice; OutputStatus output{OutputStatus::Pending}; };
SessionStatus read_first(CandidateSession& session, Frame& frame) {
  frame = {};
  bool order_stale = false;
  const auto status = session.present([&](const CandidateViewPage& page) {
    order_stale = page.order_stale;
    if (page.size) {
      frame.output = page.items[0].output;
      if (!order_stale && output_has_text(frame.output)) {
        frame.text = page.text(0);
        frame.choice = session.selection(0);
      }
    }
  });
  if (status == SessionStatus::Ready && order_stale)
    return SessionStatus::NeedsRankRestart;
  return status;
}
// 选择事件或宿主已批准的自动请求；不能仅凭 request 自动调用这个函数。
CommitResult confirm(wb::DirectQueryBinding& binding, CandidateSession& session,
                     const SelectionHandle& choice, wb::CommitReason reason) {
  auto result = binding.confirm(choice, reason);
  for (std::size_t n = 0; result.status == CommitStatus::Preparing; ++n) {
    if (n == limit) throw std::runtime_error("Wubi commit did not finish");
    binding.tick(budget);
    result = session.commit_result();
  }
  return result; // Stale、OutputRestricted、UnknownOutcome 等不自动重试。
}
} // namespace docs_wubi
 依次以 a、b、c、d 调用 key(binding, session, 1, character)。先检查 edit：InvalidCode 或 Full 时保留原编码，Busy 时暂存事件。再检查 step.shared.status：Ready 后调用 read_first() 复制候选，NoMatches 时清空显示，其他终止状态保留错误并停止使用该次结果。key() 仅用于这个无学习 Host 的基础模式，不要把每轮调度都改成 restart_first()。 read_first() 返回 Ready 表示页面读取成功，仍需检查 frame.output。只有 output_has_text(frame.output) 为真时才显示文字并提供确认操作；没有有效文字时展示实际输出状态，例如 OutputStatus::Blocked，不把它当成没有匹配候选。返回 NeedsRankRestart 表示排序已过期，应重新建立当前排序并刷新显示；这一帧不保留可确认的选择。 当最后一步含有自动请求，先核对 step.code_revision == decoder.plan().revision，确认编辑目标仍有效、应用允许自动提交且候选输出有效，再向 confirm() 传入 step.selection 与 AutoUniqueFullCode。显式选择则传入显示帧保存的 choice 与 Explicit。接收结果以 CommitResult::status 为准；Stale 要刷新候选，UnknownOutcome 要核对接收端，不能再次插入文字。 查询与提交中的循环是 CLI 示例的等待方式。界面程序应将每个 binding.tick() 安排到事件循环，保留本次查询状态；不要同时再调用 session.tick() 驱动同一个会话。达到宿主步数上限不会自动取消引擎工作。可对照真实运行输出，观察请求出现前后 sink_calls 的变化。
